<?php
namespace App\Http\Controllers;use App\Models\TransportService;use Carbon\Carbon;use Illuminate\Http\Request;
class TransportCalendarController extends Controller{public function index(Request$r){$anchor=$r->filled('date')?Carbon::parse($r->date):today();$mode=$r->input('mode','week');if($mode==='month'){$from=$anchor->copy()->startOfMonth();$to=$anchor->copy()->endOfMonth();}elseif($mode==='day'){$from=$anchor->copy()->startOfDay();$to=$anchor->copy()->endOfDay();}else{$mode='week';$from=$anchor->copy()->startOfWeek();$to=$anchor->copy()->endOfWeek();}$services=TransportService::forCompany($r->user()->company_id)->with(['vehicle','driver.employee'])->whereBetween('scheduled_start_at',[$from,$to])->orderBy('scheduled_start_at')->get()->groupBy(fn($s)=>$s->service_date->toDateString());return view('transport.calendar',compact('anchor','mode','from','to','services'));}}
